Confirmed: passing a `FastMCP` server instance directly to `Client()` uses the in-memory `FastMCPTransport`, and `read_resource()` returns a list of `TextResourceContents`/`BlobResourceContents`.

```python
import asyncio

from fastmcp import FastMCP, Client

mcp = FastMCP("Example Server")


@mcp.resource("data://config")
def get_config() -> dict:
    return {"debug": True, "env": "production"}


async def main() -> None:
    client = Client(mcp)  # in-memory transport: no subprocess, no network
    async with client:
        contents = await client.read_resource("data://config")
        for item in contents:
            if hasattr(item, "text"):
                print(item.text)
            else:
                print(item.blob)


if __name__ == "__main__":
    asyncio.run(main())
